cd /workspace/submission && find . -name "__pycache__" -type d | head; python3 - <<'PYEOF'
import os, pathlib, stat
root = pathlib.Path('/workspace/submission')
count = 0; size = 0; problems = []
for base, dirs, files in os.walk(root, followlinks=False):
    for name in dirs + files:
        path = pathlib.Path(base)/name
        st = path.lstat()
        count += 1
        if stat.S_ISREG(st.st_mode):
            size += st.st_size
        elif not stat.S_ISDIR(st.st_mode):
            problems.append(str(path))
        if stat.S_ISREG(st.st_mode) and st.st_nlink != 1:
            problems.append('hardlink ' + str(path))
print('entries', count, 'bytes', size, 'problems', problems)
for path in sorted(root.rglob('*')):
    if path.is_file():
        print('%9d %s' % (path.stat().st_size, path.relative_to(root)))
PYEOF
